                for c0 in range(w):
                    for c1 in range(c0 + 1, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if area < 4:
                            continue
                        count = sum(
                            grid[r][c] == color
                            for r in range(r0, r1 + 1)
                            for c in range(c0, c1 + 1)
                        )
                        if count / area >= 0.68:
                            for r in range(r0, r1 + 1):
                                for c in range(c0, c1 + 1):
                                    if keep[r][c] is None or keep[r][c] == color:
                                        keep[r][c] = color

    return [
        [keep[r][c] if keep[r][c] is not None else bg for c in range(w)]
        for r in range(h)
    ]
